def uv_commands(deps, dev_deps):
    commands = ["uv init"]
    if deps:
        commands.append("uv add " + " ".join(deps))
    if dev_deps:
        commands.append("uv add --dev " + " ".join(dev_deps))
    commands.append("uv sync")
    return commands

